import app from 'flarum/admin/app';
import ExtensionPage from 'flarum/admin/components/ExtensionPage';
import HealthCheck from './HealthCheck';
import RegisterToSearchEngines from './RegisterToSearchEngines';
import SSLPage from './SSLPage';
import Sitemap from './Sitemap';
const CORE_SETTINGS = ['forum_description'];
export default class SettingsPage extends ExtensionPage {
  oninit(vnode) {
    super.oninit(vnode);

    // Old links name the tab `?page=`. Core keys the page on every route param
    // but `tab`, so a later tab switch would remount it and lose unsaved changes.
    const page = m.route.param('page');
    if (!this.attrs.tab && typeof page === 'string') {
      m.route.set(app.route('extension', {
        id: this.extension.id,
        tab: page
      }), undefined, {
        replace: true
      });
    }
  }

  /**
   * Leaves the forum description, which belongs to the Basics page, out of the reset.
   */
  settingsFormControls() {
    const items = super.settingsFormControls();
    if (items.has('reset')) {
      const settings = (app.registry.getSettings(this.extension.id) || []).filter(e => typeof e !== 'function').filter(e => !CORE_SETTINGS.includes(e.setting)).map(e => ({
        key: e.setting,
        label: e.label
      }));
      items.setContent('reset', this.resetButton(settings, app.translator.trans('core.admin.extension.reset_settings.title_extension', {
        extensionTitle: this.extension.extra['flarum-extension'].title
      }, true), this.extension.id));
    }
    return items;
  }
  pageTabItems() {
    const items = super.pageTabItems();
    items.add('health', {
      id: 'health',
      label: app.translator.trans('fof-seo.admin.header.health_check'),
      icon: 'fas fa-heartbeat'
    }, 100);
    items.add('sitemap', {
      id: 'sitemap',
      label: app.translator.trans('fof-seo.admin.header.sitemap_info'),
      icon: 'fas fa-sitemap'
    }, 8);
    items.add('search-engines', {
      id: 'search-engines',
      label: app.translator.trans('fof-seo.admin.header.search_engines_info'),
      icon: 'fas fa-search'
    }, 6);
    items.add('ssl', {
      id: 'ssl',
      label: app.translator.trans('fof-seo.admin.header.setup_ssl'),
      icon: 'fas fa-shield-alt'
    }, 4);
    return items;
  }
  pageTabContent(tab, vnode) {
    const content = this.infoPages()[tab];
    if (!content) return super.pageTabContent(tab, vnode);
    return m("div", {
      className: "FlarumSEO"
    }, m("div", {
      className: "FlarumSeoPage-container"
    }, content()));
  }
  infoPages() {
    return {
      health: () => m(HealthCheck, null),
      sitemap: () => m(Sitemap, null),
      'search-engines': () => m(RegisterToSearchEngines, null),
      ssl: () => m(SSLPage, null)
    };
  }
}
flarum.reg.add('fof-seo', 'admin/Pages/SettingsPage', SettingsPage);